#define NP560_INPUT_BIT_MASK_DATA_33_BASE 0x003339e6u
#define NP560_INPUT_BIT_MASK_DATA_33_SOURCE 0x005039e6u
#define NP560_INPUT_BIT_MASK_DATA_33_SIZE 0x00000040u
