#define NP560_APPLICATION_NPE_PAGE_TEXT_DATA_31_BASE 0x0031f040u
#define NP560_APPLICATION_NPE_PAGE_TEXT_DATA_31_SOURCE 0x004ef040u
#define NP560_APPLICATION_NPE_PAGE_TEXT_DATA_31_SIZE 0x00000120u
