static char *np560_get_dtu_config_trace(Object *obj, Error **errp)
{
    CPUDMCUState *env = &NP560_MACHINE(obj)->cpu->env;
    uint64_t first = env->dtu_config_count -
        MIN(env->dtu_config_count, DMCU_DTU_CONFIG_TRACE_SLOTS);
    GString *text = g_string_new(NULL);
    uint64_t seq;
    unsigned i;

    g_string_append_printf(text, "{\"count\":%" PRIu64 ",\"events\":[",
                           env->dtu_config_count);
    for (seq = first; seq < env->dtu_config_count; seq++) {
        DMCUDTUConfigEvent *e = &env->dtu_config_trace[
            seq % DMCU_DTU_CONFIG_TRACE_SLOTS];
        g_string_append_printf(text,
            "%s{\"seq\":%" PRIu64 ",\"pc\":%u,\"reg\":%u,\"old\":%u,"
            "\"value\":%u,\"sp\":%u,\"fp\":%u,\"ds0\":%u,\"ds1\":%u,"
            "\"irq\":%s,\"stack\":[", seq == first ? "" : ",", seq, e->pc,
            e->reg, e->old_value, e->value, e->sp, e->fp, e->ds0, e->ds1,
            e->in_interrupt ? "true" : "false");
        for (i = 0; i < ARRAY_SIZE(e->stack); i++) {
            g_string_append_printf(text, "%s%u", i ? "," : "", e->stack[i]);
        }
        g_string_append(text, "],\"dtu\":[");
        for (i = 0; i < ARRAY_SIZE(e->dtu); i++) {
            g_string_append_printf(text, "%s%u", i ? "," : "", e->dtu[i]);
        }
        g_string_append(text, "]}");
    }
    g_string_append(text, "]}");
    return g_string_free(text, false);
}

static char *np560_get_audio_file_trace(Object *obj, Error **errp)
{
    CPUDMCUState *env = &NP560_MACHINE(obj)->cpu->env;
    uint64_t first = env->audio_file_count -
        MIN(env->audio_file_count, DMCU_AUDIO_FILE_TRACE_SLOTS);
    GString *text = g_string_new(NULL);
    uint64_t seq;
    unsigned i, array;

    g_string_append_printf(text, "{\"count\":%" PRIu64 ",\"events\":[", env->audio_file_count);
    for (seq = first; seq < env->audio_file_count; seq++) {
        DMCUAudioFileEvent *e = &env->audio_file_trace[seq % DMCU_AUDIO_FILE_TRACE_SLOTS];
        const uint16_t *values[] = {e->gpr, e->stack, e->locals, e->flags};
        const char *names[] = {"gpr", "stack", "locals", "flags"};
        const unsigned sizes[] = {ARRAY_SIZE(e->gpr), ARRAY_SIZE(e->stack),
                                  ARRAY_SIZE(e->locals), ARRAY_SIZE(e->flags)};
        g_string_append_printf(text,
            "%s{\"seq\":%" PRIu64 ",\"pc\":%u,\"previous_pc\":%u,"
            "\"sp\":%u,\"fp\":%u,\"ds0\":%u,\"ds1\":%u,\"psw\":%u,\"irq\":%s",
            seq == first ? "" : ",", seq, e->pc, e->previous_pc, e->sp, e->fp,
            e->ds0, e->ds1, e->psw, e->in_interrupt ? "true" : "false");
        for (array = 0; array < ARRAY_SIZE(values); array++) {
            g_string_append_printf(text, ",\"%s\":[", names[array]);
            for (i = 0; i < sizes[array]; i++) {
                g_string_append_printf(text, "%s%u", i ? "," : "", values[array][i]);
            }
            g_string_append(text, "]");
        }
        g_string_append(text, "}");
    }
    g_string_append(text, "]}");
    return g_string_free(text, false);
}

static uint32_t np560_nand_page(const NP560NANDState *nand)
{
    return ((uint32_t)nand->page_hi << 16) | nand->page_lo;
}

static uint32_t np560_nand_copy_destination(const NP560NANDState *nand)
{
    return ((uint32_t)nand->buffer_hi << 16) | nand->buffer_lo;
}

static hwaddr np560_nand_buffer(const NP560NANDState *nand)
{
    /* The resident API passes a normalized 32-bit far pointer.  Formatter
     * pointer arithmetic proves that 0000:32CA denotes physical bank zero;
     * the caller's live DS selectors can differ by the time BCC6 runs.
     */
    return (((hwaddr)nand->buffer_hi << 16) | nand->buffer_lo) &
           0x00ffffffu;
}

/* Scalar probes retain the controller's observed column-A0 behaviour. */
static uint32_t np560_nand_dma_column(const NP560NANDState *nand)
{
    return nand->length == 1 ? nand->column ^ 1u : nand->column;
}

static hwaddr np560_nand_dma_buffer(const NP560NANDState *nand)
{
    return np560_nand_buffer(nand) ^ (nand->length == 1 ? 1u : 0u);
}

static void np560_nand_set_failure(NP560NANDState *nand, uint16_t error)
{
    nand->status = 0;
    nand->error = error;
}

static bool np560_nand_commit(NP560NANDState *nand, unsigned operation,
                              uint32_t page, uint32_t column,
                              const uint8_t *bytes, uint32_t length)
{
    Error *error = NULL;

    if (!np560_nand_journal_append(nand->journal, operation, page, column,
                                  bytes, length, &error)) {
        error_report_err(error);
        np560_nand_set_failure(nand, NP560_NAND_ERROR_BACKING);
        return false;
    }
    return true;
}

static bool np560_nand_validate_transfer(NP560NANDState *nand,
                                         uint32_t page)
{
    uint32_t column = np560_nand_dma_column(nand);
    uint32_t oob_offset;

    if (page >= NP560_NAND_PAGES) {
        np560_nand_set_failure(nand, NP560_NAND_ERROR_PAGE);
        return false;
    }
    if (column >= NP560_NAND_PAGE_DATA) {
        uint32_t pages;

        oob_offset = column - NP560_NAND_PAGE_DATA;
        pages = DIV_ROUND_UP(oob_offset + nand->length,
                             NP560_NAND_PAGE_OOB);

        if (oob_offset > NP560_NAND_OOB_STREAM_MAX ||
            nand->length > NP560_NAND_OOB_STREAM_MAX - oob_offset ||
            page > NP560_NAND_PAGES - pages) {
            np560_nand_set_failure(nand, NP560_NAND_ERROR_RANGE);
            return false;
        }
        return true;
    }
    if (column > NP560_NAND_PAGE_TOTAL ||
        nand->length > NP560_NAND_PAGE_TOTAL - column) {
        np560_nand_set_failure(nand, NP560_NAND_ERROR_RANGE);
        return false;
    }
    return true;
}

static bool np560_nand_is_oob_stream(const NP560NANDState *nand)
{
    return np560_nand_dma_column(nand) >= NP560_NAND_PAGE_DATA;
}

static void np560_nand_copy_oob_stream(const NP560NANDState *nand,
                                       uint32_t page, uint8_t *bytes)
{
    size_t copied = 0;
    size_t offset = np560_nand_dma_column(nand) - NP560_NAND_PAGE_DATA;

    while (copied < nand->length) {
        size_t target_page = page + offset / NP560_NAND_PAGE_OOB;
        size_t target_column = offset % NP560_NAND_PAGE_OOB;
        size_t chunk = MIN((size_t)NP560_NAND_PAGE_OOB - target_column,
                           (size_t)nand->length - copied);
        memcpy(bytes + copied,
               nand->oob + target_page * NP560_NAND_PAGE_OOB + target_column,
               chunk);
        copied += chunk;
        offset += chunk;
    }
}

static void np560_nand_copy_from_page(NP560NANDState *nand, uint32_t page,
                                      uint8_t page_bytes[NP560_NAND_PAGE_TOTAL])
{
    memcpy(page_bytes,
           nand->data + (size_t)page * NP560_NAND_PAGE_DATA,
           NP560_NAND_PAGE_DATA);
    memcpy(page_bytes + NP560_NAND_PAGE_DATA,
           nand->oob + (size_t)page * NP560_NAND_PAGE_OOB,
           NP560_NAND_PAGE_OOB);
}

static uint32_t np560_nand_trace_hash(const uint8_t *bytes, size_t length)
{
    uint32_t hash = 2166136261u;
    size_t i;

    for (i = 0; i < length; i++) {
        hash = (hash ^ bytes[i]) * 16777619u;
    }
    return hash;
}

static uint16_t np560_burner_command(void)
{
    uint8_t bytes[2];

    if (address_space_read(&address_space_memory, 0x500008,
                           MEMTXATTRS_UNSPECIFIED, bytes,
                           sizeof(bytes)) != MEMTX_OK) {
        return 0xffff;
    }
    return lduw_le_p(bytes);
}

static void np560_nand_log_page3f_event(const NP560NANDState *nand,
                                        uint32_t slot, const char *event)
{
    qemu_log_mask(LOG_UNIMP,
                  "np560 page3f %s burner-command=%u nand-command=%u "
                  "pc=%06x caller=%06x parent=%06x page=%08x "
                  "column=%04x length=%04x buffer=%06x flags=%04x "
                  "hash=%08x prefix="
                  "%02x%02x%02x%02x%02x%02x%02x%02x\n",
                  event, np560_burner_command(),
                  nand->trace_command[slot], nand->trace_pc[slot],
                  nand->trace_caller[slot], nand->trace_parent[slot],
                  nand->trace_page[slot], nand->trace_column[slot],
                  nand->trace_length[slot], nand->trace_buffer[slot],
                  nand->trace_flags[slot], nand->trace_hash[slot],
                  nand->trace_prefix[slot][0], nand->trace_prefix[slot][1],
                  nand->trace_prefix[slot][2], nand->trace_prefix[slot][3],
                  nand->trace_prefix[slot][4], nand->trace_prefix[slot][5],
                  nand->trace_prefix[slot][6], nand->trace_prefix[slot][7]);
}

static void np560_nand_trace_payload(NP560NANDState *nand, uint32_t slot,
                                     const uint8_t *bytes, size_t length)
{
    size_t prefix = MIN(length, (size_t)NP560_NAND_TRACE_PREFIX);

    nand->trace_hash[slot] = np560_nand_trace_hash(bytes, length);
    memcpy(nand->trace_prefix[slot], bytes, prefix);
}

/*
 * The block-zero factory record that seeds globals 4A36/4A38 begins with this
 * exact byte sequence.  Keep a persistent first/last record here because the
 * normal sixteen-entry NAND ring is overwritten within a fraction of a second
 * during V3.80's storage scan.
 */
static void np560_nand_trace_cafe_record(NP560NANDState *nand, uint32_t slot,
                                         const uint8_t *bytes, size_t length)
{
    static const uint8_t signature[] = {
        0xfe, 0xca, 0x93, 0x0e, 0x58, 0x01, 0x42, 0x4b,
    };
    size_t offset;

    if (length < sizeof(signature)) {
        return;
    }
    for (offset = 0; offset <= length - sizeof(signature); offset++) {
        size_t prefix;

        if (memcmp(bytes + offset, signature, sizeof(signature))) {
            continue;
        }
        nand->cafe_record_reads++;
        prefix = MIN(length - offset, (size_t)NP560_NAND_CAFE_PREFIX);
        if (nand->cafe_record_reads == 1) {
            nand->cafe_first_pc = nand->trace_pc[slot];
            nand->cafe_first_caller = nand->trace_caller[slot];
            nand->cafe_first_parent = nand->trace_parent[slot];
            nand->cafe_first_page = nand->trace_page[slot];
            nand->cafe_first_buffer = nand->trace_buffer[slot] + offset;
            nand->cafe_first_column = nand->trace_column[slot] + offset;
            nand->cafe_first_length = nand->trace_length[slot];
            nand->cafe_first_flags = nand->trace_flags[slot];
            nand->cafe_first_offset = offset;
            memset(nand->cafe_first_prefix, 0,
                   sizeof(nand->cafe_first_prefix));
            memcpy(nand->cafe_first_prefix, bytes + offset, prefix);
        }
        nand->cafe_pc = nand->trace_pc[slot];
        nand->cafe_caller = nand->trace_caller[slot];
        nand->cafe_parent = nand->trace_parent[slot];
        nand->cafe_page = nand->trace_page[slot];
        nand->cafe_buffer = nand->trace_buffer[slot] + offset;
        nand->cafe_column = nand->trace_column[slot] + offset;
        nand->cafe_length = nand->trace_length[slot];
        nand->cafe_flags = nand->trace_flags[slot];
        nand->cafe_offset = offset;
        memset(nand->cafe_prefix, 0, sizeof(nand->cafe_prefix));
        memcpy(nand->cafe_prefix, bytes + offset, prefix);
    }
}

static void np560_nand_trace_page3f(NP560NANDState *nand, uint32_t slot,
                                    uint32_t effective_page)
{
    if (effective_page != 0x3f) {
        return;
    }
    if (nand->page3f_programs == 1) {
        nand->page3f_first_pc = nand->trace_pc[slot];
        nand->page3f_first_caller = nand->trace_caller[slot];
        nand->page3f_first_buffer = nand->trace_buffer[slot];
        nand->page3f_first_hash = nand->trace_hash[slot];
        nand->page3f_first_command = nand->trace_command[slot];
        nand->page3f_first_column = nand->trace_column[slot];
        nand->page3f_first_length = nand->trace_length[slot];
        nand->page3f_first_flags = nand->trace_flags[slot];
        memcpy(nand->page3f_first_prefix, nand->trace_prefix[slot],
               sizeof(nand->page3f_first_prefix));
    }
    nand->page3f_pc = nand->trace_pc[slot];
    nand->page3f_caller = nand->trace_caller[slot];
    nand->page3f_buffer = nand->trace_buffer[slot];
    nand->page3f_hash = nand->trace_hash[slot];
    nand->page3f_command = nand->trace_command[slot];
    nand->page3f_column = nand->trace_column[slot];
    nand->page3f_length = nand->trace_length[slot];
    nand->page3f_flags = nand->trace_flags[slot];
    memcpy(nand->page3f_prefix, nand->trace_prefix[slot],
           sizeof(nand->page3f_prefix));
}

static void np560_nand_trace_maskrom(NP560NANDState *nand,
                                     const CPUDMCUState *env,
                                     const uint8_t *bytes, size_t length,
                                     uint32_t page, hwaddr buffer)
{
    static const uint8_t landmark[] = "MASKROM";
    size_t i;

    if (length < sizeof(landmark) - 1) {
        return;
    }
    for (i = 0; i <= length - (sizeof(landmark) - 1); i++) {
        if (!memcmp(bytes + i, landmark, sizeof(landmark) - 1)) {
            nand->maskrom_writes++;
            nand->maskrom_page = page;
            nand->maskrom_buffer = buffer;
            nand->maskrom_pc = env ? env->pc & 0x00ffffffu : 0;
            nand->maskrom_command = nand->command;
            nand->maskrom_column = nand->column;
            nand->maskrom_offset = i;
            nand->maskrom_length = length;
            return;
        }
    }
}

static void np560_nand_execute(NP560MachineState *s)
{
    NP560NANDState *nand = &s->nand;
    CPUDMCUState *env = s->cpu ? &s->cpu->env : NULL;
    uint8_t page_bytes[NP560_NAND_PAGE_TOTAL];
    uint8_t oob_stream[NP560_NAND_OOB_STREAM_MAX];
    uint32_t page = np560_nand_page(nand);
    uint32_t column = np560_nand_dma_column(nand);
    hwaddr logical_buffer = nand->command == NP560_NAND_CMD_COPY_BACK ?
        np560_nand_copy_destination(nand) : np560_nand_buffer(nand);
    hwaddr buffer = nand->command == NP560_NAND_CMD_COPY_BACK ?
        logical_buffer : np560_nand_dma_buffer(nand);
    uint32_t trace_slot = nand->trace_index++ % NP560_NAND_TRACE;
    MemTxResult result;
    unsigned i;

    nand->trace_pc[trace_slot] = env ? env->pc & 0x00ffffffu : 0;
    nand->trace_caller[trace_slot] = 0;
    nand->trace_parent[trace_slot] = env ? env->nand_manager_caller : 0;
    if (env) {
        uint32_t count = MIN(env->control_trace_count,
                             (uint32_t)DMCU_CONTROL_TRACE_WORDS);
        uint32_t n;
        uint32_t expected_target = 0;

        switch (nand->command) {
        case NP560_NAND_CMD_READ_PAGE:
            expected_target = 0x02bbf6u;
            break;
        case NP560_NAND_CMD_PROGRAM_PAGE:
            expected_target = 0x02bcc6u;
            break;
        case NP560_NAND_CMD_ERASE_BLOCK:
            expected_target = 0x02bdd6u;
            break;
        default:
            break;
        }

        for (n = 0; n < count; n++) {
            uint32_t index = env->control_trace_count - 1 - n;
            uint32_t slot = index % DMCU_CONTROL_TRACE_WORDS;
            uint32_t target = env->control_trace_to[slot] & 0x00ffffffu;

            if ((expected_target && target == expected_target) ||
                (nand->command == NP560_NAND_CMD_COPY_BACK &&
                 (target == 0x02be5cu || target == 0x02bf56u))) {
                nand->trace_caller[trace_slot] =
                    env->control_trace_from[slot] & 0x00ffffffu;
                break;
            }
        }
        if (nand->command == NP560_NAND_CMD_ERASE_BLOCK &&
            nand->trace_parent[trace_slot] == 0) {
            for (n = 0; n < count; n++) {
                uint32_t index = env->control_trace_count - 1 - n;
                uint32_t slot = index % DMCU_CONTROL_TRACE_WORDS;

                if ((env->control_trace_to[slot] & 0x00ffffffu) ==
                    0x507dd8u) {
                    nand->trace_parent[trace_slot] =
                        env->control_trace_from[slot] & 0x00ffffffu;
                    break;
                }
            }
        }
    }
    nand->trace_page[trace_slot] = page;
    nand->trace_buffer[trace_slot] = logical_buffer;
    nand->trace_hash[trace_slot] = 0;
    nand->trace_command[trace_slot] = nand->command;
    nand->trace_column[trace_slot] = nand->column;
    nand->trace_length[trace_slot] = nand->length;
    nand->trace_flags[trace_slot] = nand->flags;
    memset(nand->trace_prefix[trace_slot], 0, NP560_NAND_TRACE_PREFIX);

    /*
     * V3.80's formatter writes the logical-to-physical block map through
     * 50:8476 -> 02:BCC6.  Keep this diagnostic behind QEMU's unimplemented
     * log mask so normal runs stay quiet while ROM-ABI investigations can
     * recover the exact page sequence without changing guest state.
     */
    if (nand->command == NP560_NAND_CMD_PROGRAM_PAGE &&
        nand->trace_caller[trace_slot] == 0x508476u) {
        uint8_t map_slice[NP560_NAND_FTL_SECTOR_DATA +
                          NP560_NAND_FTL_SECTOR_ECC];
        unsigned slice;

        qemu_log_mask(LOG_UNIMP,
                      "np560 map program caller=%06x pc=%06x page=%08x "
                      "column=%04x buffer=%08" HWADDR_PRIx
                      " length=%04x flags=%04x\n",
                      nand->trace_caller[trace_slot],
                      nand->trace_pc[trace_slot], page, nand->column,
                      logical_buffer, nand->length, nand->flags);
        for (slice = 0; slice < 4; slice++) {
            MemTxResult slice_result = address_space_read(
                &address_space_memory,
                logical_buffer + slice * sizeof(map_slice),
                MEMTXATTRS_UNSPECIFIED, map_slice, sizeof(map_slice));

            if (slice_result != MEMTX_OK) {
                qemu_log_mask(LOG_UNIMP,
                              "np560 map buffer slice=%u dma-error=%u\n",
                              slice, slice_result);
                continue;
            }
            qemu_log_mask(LOG_UNIMP,
                          "np560 map buffer slice=%u hash=%08x "
                          "words=%04x,%04x,%04x,%04x,%04x,%04x,%04x,%04x\n",
                          slice,
                          np560_nand_trace_hash(map_slice, sizeof(map_slice)),
                          lduw_le_p(map_slice + 0),
                          lduw_le_p(map_slice + 2),
                          lduw_le_p(map_slice + 4),
                          lduw_le_p(map_slice + 6),
                          lduw_le_p(map_slice + 8),
                          lduw_le_p(map_slice + 10),
                          lduw_le_p(map_slice + 12),
                          lduw_le_p(map_slice + 14));
        }
    }

    nand->status = 0;
    nand->error = NP560_NAND_ERROR_NONE;
    switch (nand->command) {
    case NP560_NAND_CMD_READ_PAGE:
        if (!np560_nand_validate_transfer(nand, page)) {
            return;
        }
        if (np560_nand_is_oob_stream(nand)) {
            np560_nand_copy_oob_stream(nand, page, oob_stream);
        } else {
            np560_nand_copy_from_page(nand, page, page_bytes);
        }
        result = address_space_write(
            &address_space_memory, buffer, MEMTXATTRS_UNSPECIFIED,
            np560_nand_is_oob_stream(nand) ?
            oob_stream : page_bytes + column,
            nand->length);
        if (result != MEMTX_OK) {
            np560_nand_set_failure(nand, NP560_NAND_ERROR_DMA);
            return;
        }
        np560_nand_trace_payload(nand, trace_slot,
                                 np560_nand_is_oob_stream(nand) ?
                                 oob_stream : page_bytes + column,
                                 nand->length);
        if (env && page == 0x1004bu && column == 0 &&
            nand->length == NP560_NAND_PAGE_TOTAL) {
            /* The isolated hero-game checkpoint maps the first sector of
             * application-directory cluster 5 to this physical page.  Arm a
             * bounded read-only control trace at each exact DMA completion so
             * the directory parser/filter path survives later UI redraws.
             * The latest read is the one immediately preceding the browser
             * controller.  No guest-visible state is modified. */
            env->control_trace_count = 0;
            env->control_trace_frozen = false;
            env->npe_directory_trace_remaining = DMCU_CONTROL_TRACE_WORDS;
            env->npe_directory_trace_triggered = true;
            env->npe_directory_data_read_count = 0;
        }
        if (!np560_nand_is_oob_stream(nand)) {
            np560_nand_trace_cafe_record(nand, trace_slot,
                                         page_bytes + column,
                                         nand->length);
        }
        if ((page == 0x2007fu || page == 0x3007fu) &&
            nand->length >= 0x40) {
            const uint8_t *payload = np560_nand_is_oob_stream(nand) ?
                oob_stream : page_bytes + column;

            qemu_log_mask(LOG_UNIMP,
                          "np560 FTL tail read block=%04x page=%08x "
                          "state=%02x,%02x,%02x ids=%04x,%04x,%04x "
                          "caller=%06x\n",
                          page / NP560_NAND_PAGES_PER_BLOCK, page,
                          payload[0x37], payload[0x38], payload[0x39],
                          lduw_le_p(payload + 0x3a),
                          lduw_le_p(payload + 0x3c),
                          lduw_le_p(payload + 0x3e),
                          nand->trace_caller[trace_slot]);
        }
        if (nand->trace_caller[trace_slot] == 0x2783eau) {
            qemu_log_mask(LOG_UNIMP,
                          "np560 FTL map read page=%08x column=%04x "
                          "length=%04x hash=%08x prefix="
                          "%02x%02x%02x%02x%02x%02x%02x%02x\n",
                          page, nand->column, nand->length,
                          nand->trace_hash[trace_slot],
                          nand->trace_prefix[trace_slot][0],
                          nand->trace_prefix[trace_slot][1],
                          nand->trace_prefix[trace_slot][2],
                          nand->trace_prefix[trace_slot][3],
                          nand->trace_prefix[trace_slot][4],
                          nand->trace_prefix[trace_slot][5],
                          nand->trace_prefix[trace_slot][6],
                          nand->trace_prefix[trace_slot][7]);
        }
        if (page == 0x3f && !np560_nand_is_oob_stream(nand)) {
            np560_nand_log_page3f_event(nand, trace_slot, "read");
        }
        nand->page_reads++;
        nand->status = 1;
        return;
    case NP560_NAND_CMD_PROGRAM_PAGE:
        if (!np560_nand_validate_transfer(nand, page)) {
            return;
        }
        if (np560_nand_is_oob_stream(nand)) {
            size_t copied;

            result = address_space_read(&address_space_memory, buffer,
                                        MEMTXATTRS_UNSPECIFIED, oob_stream,
                                        nand->length);
            if (result != MEMTX_OK) {
                np560_nand_set_failure(nand, NP560_NAND_ERROR_DMA);
                return;
            }
            np560_nand_trace_payload(nand, trace_slot, oob_stream,
                                     nand->length);
            if (!np560_nand_commit(nand, NP560_JOURNAL_OOB, page, column,
                                   oob_stream, nand->length)) {
                return;
            }
            for (copied = 0; copied < nand->length; copied++) {
                size_t offset = column - NP560_NAND_PAGE_DATA + copied;
                uint32_t target_page =
                    page + offset / NP560_NAND_PAGE_OOB;
                unsigned target_column = offset % NP560_NAND_PAGE_OOB;

                nand->oob[(size_t)target_page * NP560_NAND_PAGE_OOB +
                          target_column] &= oob_stream[copied];
            }
            nand->page_programs++;
            nand->status = 1;
            return;
        }
        np560_nand_copy_from_page(nand, page, page_bytes);
        result = address_space_read(&address_space_memory, buffer,
                                    MEMTXATTRS_UNSPECIFIED,
                                    page_bytes + column, nand->length);
        if (result != MEMTX_OK) {
            np560_nand_set_failure(nand, NP560_NAND_ERROR_DMA);
            return;
        }
        np560_nand_trace_payload(nand, trace_slot,
                                 page_bytes + column, nand->length);
        if (nand->trace_caller[trace_slot] == 0x1c2f4eu ||
            nand->trace_caller[trace_slot] == 0x278308u) {
            qemu_log_mask(LOG_UNIMP,
                          "np560 FTL map program caller=%06x page=%08x "
                          "column=%04x length=%04x hash=%08x prefix="
                          "%02x%02x%02x%02x%02x%02x%02x%02x\n",
                          nand->trace_caller[trace_slot], page,
                          nand->column, nand->length,
                          nand->trace_hash[trace_slot],
                          nand->trace_prefix[trace_slot][0],
                          nand->trace_prefix[trace_slot][1],
                          nand->trace_prefix[trace_slot][2],
                          nand->trace_prefix[trace_slot][3],
                          nand->trace_prefix[trace_slot][4],
                          nand->trace_prefix[trace_slot][5],
                          nand->trace_prefix[trace_slot][6],
                          nand->trace_prefix[trace_slot][7]);
        }
        if (page == 0x3f) {
            nand->page3f_programs++;
            np560_nand_trace_page3f(nand, trace_slot, page);
            np560_nand_log_page3f_event(nand, trace_slot, "program");
        }
        np560_nand_trace_maskrom(nand, env, page_bytes + column,
                                 nand->length, page, logical_buffer);
        /* NAND programming can only change one bits to zero bits. */
        if (!np560_nand_commit(nand, NP560_JOURNAL_PROGRAM, page, column,
                               page_bytes + column, nand->length)) {
            return;
        }
        for (i = column; i < column + nand->length; i++) {
            if (i < NP560_NAND_PAGE_DATA) {
                nand->data[(size_t)page * NP560_NAND_PAGE_DATA + i] &=
                    page_bytes[i];
            } else {
                nand->oob[(size_t)page * NP560_NAND_PAGE_OOB +
                          i - NP560_NAND_PAGE_DATA] &= page_bytes[i];
            }
        }
        nand->page_programs++;
        nand->status = 1;
        return;
    case NP560_NAND_CMD_ERASE_BLOCK:
        if (page >= NP560_NAND_PAGES) {
            np560_nand_set_failure(nand, NP560_NAND_ERROR_PAGE);
            return;
        }
        page -= page % NP560_NAND_PAGES_PER_BLOCK;
        if (page == 0x20040u || page == 0x30040u) {
            qemu_log_mask(LOG_UNIMP,
                          "np560 FTL data-block erase block=%04x page=%08x "
                          "caller=%06x pc=%06x parent=%06x\n",
                          page / NP560_NAND_PAGES_PER_BLOCK, page,
                          nand->trace_caller[trace_slot],
                          nand->trace_pc[trace_slot],
                          nand->trace_parent[trace_slot]);
        }
        if (page <= 0x3f && 0x3f < page + NP560_NAND_PAGES_PER_BLOCK) {
            nand->page3f_erases++;
            if (nand->page3f_erases == 1) {
                nand->page3f_erase_first_pc = nand->trace_pc[trace_slot];
                nand->page3f_erase_first_caller =
                    nand->trace_caller[trace_slot];
                nand->page3f_erase_first_parent =
                    nand->trace_parent[trace_slot];
                nand->page3f_erase_first_page =
                    nand->trace_page[trace_slot];
                nand->page3f_erase_first_flags =
                    nand->trace_flags[trace_slot];
            }
            nand->page3f_erase_pc = nand->trace_pc[trace_slot];
            nand->page3f_erase_caller = nand->trace_caller[trace_slot];
            nand->page3f_erase_parent = nand->trace_parent[trace_slot];
            nand->page3f_erase_page = nand->trace_page[trace_slot];
            nand->page3f_erase_flags = nand->trace_flags[trace_slot];
            np560_nand_log_page3f_event(nand, trace_slot, "erase");
        }
        if (!np560_nand_commit(nand, NP560_JOURNAL_ERASE, page, 0, NULL, 0)) {
            return;
        }
        memset(nand->data + (size_t)page * NP560_NAND_PAGE_DATA, 0xff,
               NP560_NAND_PAGES_PER_BLOCK * NP560_NAND_PAGE_DATA);
        memset(nand->oob + (size_t)page * NP560_NAND_PAGE_OOB, 0xff,
               NP560_NAND_PAGES_PER_BLOCK * NP560_NAND_PAGE_OOB);
        nand->block_erases++;
        nand->status = 1;
        return;
    case NP560_NAND_CMD_READ_ID:
        nand->id_reads++;
        nand->status = 1;
        return;
    case NP560_NAND_CMD_COPY_BACK: {
        uint32_t destination = np560_nand_copy_destination(nand);

        if (!np560_nand_validate_transfer(nand, page)) {
            return;
        }
        if (destination >= NP560_NAND_PAGES) {
            np560_nand_set_failure(nand, NP560_NAND_ERROR_PAGE);
            return;
        }
        np560_nand_copy_from_page(nand, page, page_bytes);
        np560_nand_trace_payload(nand, trace_slot, page_bytes,
                                 NP560_NAND_PAGE_TOTAL);
        if (destination == 0x3f) {
            nand->page3f_programs++;
            nand->page3f_copies++;
            np560_nand_trace_page3f(nand, trace_slot, destination);
        }
        np560_nand_trace_maskrom(nand, env, page_bytes,
                                 NP560_NAND_PAGE_TOTAL, destination, buffer);
        /* Copy-back is still NAND programming: only one-to-zero changes. */
        if (!np560_nand_commit(nand, NP560_JOURNAL_PROGRAM, destination, 0,
                               page_bytes, NP560_NAND_PAGE_TOTAL)) {
            return;
        }
        for (i = 0; i < NP560_NAND_PAGE_TOTAL; i++) {
            if (i < NP560_NAND_PAGE_DATA) {
                nand->data[(size_t)destination * NP560_NAND_PAGE_DATA + i] &=
                    page_bytes[i];
            } else {
                nand->oob[(size_t)destination * NP560_NAND_PAGE_OOB +
                          i - NP560_NAND_PAGE_DATA] &= page_bytes[i];
            }
        }
        nand->page_reads++;
        nand->page_programs++;
        nand->page_copies++;
        nand->status = 1;
        return;
    }
    default:
        np560_nand_set_failure(nand, NP560_NAND_ERROR_COMMAND);
        return;
    }
}

