static char *np560_get_lcd_state(Object *obj, Error **errp)
{
    NP560ST7529State *lcd = &NP560_MACHINE(obj)->lcd;
    GString *text;
    uint32_t gram_hash[3] = { 2166136261u, 2166136261u, 2166136261u };
    uint32_t gram_nonzero[3] = { 0, 0, 0 };
    uint64_t first;
    uint64_t sequence;
    unsigned x;
    unsigned y;

    /*
     * Keep the three controller-line bands observable independently.  The
     * application framebuffer normally writes lines 20..139, while a real
     * NP560 photograph shows a narrow status strip above that surface.  Raw
     * GRAM occupancy tells us whether lines 0..19 already contain guest LCD
     * output before changing the modeled glass geometry.  This is strictly
     * diagnostic: it neither maps nor modifies any displayed pixel.
     */
    for (y = 0; y < NP560_ST7529_RAM_LINES; y++) {
        unsigned band = y < NP560_LCD_VISIBLE_LINE ? 0 :
                        y < NP560_LCD_VISIBLE_LINE + DMCU_LCD_HEIGHT ? 1 : 2;

        for (x = 0; x < DMCU_LCD_WIDTH; x++) {
            uint8_t level = lcd->gram[y][x] & 0x1f;

            gram_hash[band] ^= level;
            gram_hash[band] *= 16777619u;
            if (level) {
                gram_nonzero[band]++;
            }
        }
    }

    text = g_string_new(NULL);
    g_string_append_printf(text,
        "ST7529 DISPLAY=%s SLEEP=%s INV=%s EXT=%u CMD=%02x "
        "COM=%u DUTY=%u SCAN=%02x,%02x,%02x WINDOW=C%u-%u,L%u-%u "
        "CUR=C%u,L%u,P%u COMMANDS=%" G_GUINT64_FORMAT
        " DATA=%" G_GUINT64_FORMAT " FRAMES=%" G_GUINT64_FORMAT
        " ENCODING=gray5-darkness PARAM=%u/%u",
        lcd->display_on ? "on" : "off", lcd->sleeping ? "on" : "off",
        lcd->inverse ? "on" : "off", lcd->extended, lcd->command,
        lcd->com_scan, lcd->display_lines,
        lcd->scan[0], lcd->scan[1], lcd->scan[2],
        lcd->column_start, lcd->column_end, lcd->line_start, lcd->line_end,
        lcd->column, lcd->line, lcd->pixel, lcd->command_writes,
        lcd->data_writes, lcd->completed_frames,
        lcd->parameter_index, lcd->parameter_count);
    for (unsigned bank = 0; bank < 2; bank++) {
        g_string_append_printf(text, " GRAY%u=", bank + 1);
        if (!lcd->gray_pwm_programmed[bank]) {
            g_string_append(text, "unknown");
        } else {
            for (unsigned i = 0; i < 16; i++) {
                g_string_append_printf(text, "%s%02x", i ? "," : "",
                                       lcd->gray_pwm[bank][i]);
            }
        }
    }
    g_string_append(text, " PWM=unmodeled");
    g_string_append_printf(text,
        " GRAM=L0-19:%u/%08x,L20-139:%u/%08x,L140-159:%u/%08x",
        gram_nonzero[0], gram_hash[0], gram_nonzero[1], gram_hash[1],
        gram_nonzero[2], gram_hash[2]);
    if (lcd->status_write_count) {
        uint64_t count = MIN(lcd->status_write_count,
                             (uint64_t)NP560_ST7529_STATUS_TRACE);
        uint64_t first_status = lcd->status_write_count - count;
        uint64_t index;

        g_string_append_printf(text,
            " STATUS_WRITES=%" G_GUINT64_FORMAT " TRACE=",
            lcd->status_write_count);
        for (index = first_status; index < lcd->status_write_count; index++) {
            uint32_t slot = index % NP560_ST7529_STATUS_TRACE;
            uint32_t pc = lcd->status_write_pc[slot];

            uint32_t caller = lcd->status_write_caller[slot];
            uint32_t parent = lcd->status_write_parent[slot];

            g_string_append_printf(text,
                "%s%02x:%04x<%02x:%04x<%02x:%04x@%u,%u=%u",
                index == first_status ? "" : ",",
                (pc >> 16) & 0xff, pc & 0xffff,
                (caller >> 16) & 0xff, caller & 0xffff,
                (parent >> 16) & 0xff, parent & 0xffff,
                lcd->status_write_x[slot], lcd->status_write_y[slot],
                lcd->status_write_level[slot]);
        }
    }
    first = lcd->completed_frames > NP560_ST7529_FRAME_TRACE ?
        lcd->completed_frames - NP560_ST7529_FRAME_TRACE + 1 : 1;
    g_string_append(text, " TRACE=");
    for (sequence = first; sequence <= lcd->completed_frames; sequence++) {
        unsigned slot = (sequence - 1) % NP560_ST7529_FRAME_TRACE;
        uint32_t pc;
        uint32_t caller;
        uint32_t parent;

        if (lcd->frame_sequence[slot] != sequence) {
            continue;
        }
        pc = lcd->frame_pc[slot];
        caller = lcd->frame_caller[slot];
        parent = lcd->frame_parent[slot];
        g_string_append_printf(text,
            "%s%" G_GUINT64_FORMAT "@%02x:%04x<%02x:%04x<%02x:%04x"
            "(%04x,%04x,%04x;D%03x)/%08x/%08x/%" G_GUINT64_FORMAT,
            sequence == first ? "" : ",", sequence,
            (pc >> 16) & 0xff, pc & 0xffff,
            (caller >> 16) & 0xff, caller & 0xffff,
            (parent >> 16) & 0xff, parent & 0xffff,
            lcd->frame_args[slot][0], lcd->frame_args[slot][1],
            lcd->frame_args[slot][2], lcd->frame_ds0[slot],
            lcd->frame_hash[slot],
            lcd->frame_levels[slot], lcd->frame_data_writes[slot]);
    }
    return g_string_free(text, false);
}

